6	/**
7	 * Create-time guard for {@code POST /owners}: validates {@code postcode} <em>only when present</em>.
8	 * A supplied postcode must be exactly four digits and, when the city maps to a known region, fall
9	 * within that region's inclusive range; otherwise the request is rejected with 400 via
10	 * {@link InvalidPostcodeException}. A city with no known region accepts any 4-digit postcode, and
11	 * an absent (null/blank) postcode is accepted unchanged — so the request contract stays
12	 * backward-compatible.
13	 *
14	 * <p>The city-to-region decision comes from {@link OwnerLocality}, the single shared table also
15	 * used by {@code OwnerMapper.locality} for the read-time {@code locality}, so the two sides of the
16	 * rule cannot drift.
17	 */
18	public class ValidateOwnerPostcode {
19	
20	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
21	        String postcode = request.getPostcode();
22	        if (postcode == null || postcode.isBlank()) {
23	            return; // optional when absent
24	        }
25	        if (!postcode.matches("[0-9]{4}")) {
26	            throw new InvalidPostcodeException(postcode);
27	        }
28	        String region = OwnerLocality.regionForCity(request.getCity());
29	        int[] range = OwnerLocality.postcodeRange(region);
30	        if (range != null) {
31	            int value = Integer.parseInt(postcode);
32	            if (value < range[0] || value > range[1]) {
33	                throw new InvalidPostcodeException(postcode);
34	            }
35	        }
36	    }
37	}
